	<div class="add-update-preview">
		<el-form
			class="add-update-form"
			ref="ruleForm"
			:model="ruleForm"
			:rules="rules"
			label-width="200px"
			>
			<el-form-item class="add-item" label="订单编号" prop="shenqingbianhao">
				<el-input v-model="ruleForm.shenqingbianhao" 
					placeholder="订单编号" clearable :readonly="ro.shenqingbianhao"></el-input>
			</el-form-item>
			<el-form-item class="add-item" label="资源名称" prop="ziyuanmingcheng">
				<el-input v-model="ruleForm.ziyuanmingcheng" 
					placeholder="资源名称" clearable :readonly="ro.ziyuanmingcheng"></el-input>
			</el-form-item>
			<el-form-item class="add-item" label="资源图片" v-if="type!='cross' || (type=='cross' && !ro.ziyuantupian)" prop="ziyuantupian">
				<file-upload
					tip="点击上传资源图片"
					action="file/upload"
					:limit="3"
					:multiple="true"
					:disabled="ro.ziyuantupian"
					:fileUrls="ruleForm.ziyuantupian?ruleForm.ziyuantupian:''"
					@change="ziyuantupianUploadChange"
					></file-upload>
			</el-form-item>
			<el-form-item class="add-item" v-else label="资源图片" prop="ziyuantupian">
				<img v-if="ruleForm.ziyuantupian.substring(0,4)=='http'" class="upload-img" v-bind:key="index" :src="ruleForm.ziyuantupian.split(',')[0]">
				<img v-else class="upload-img" v-bind:key="index" v-for="(item,index) in ruleForm.ziyuantupian.split(',')" :src="baseUrl+item">
			</el-form-item>
			<el-form-item class="add-item" label="资源分类" prop="ziyuanfenlei">
				<el-input v-model="ruleForm.ziyuanfenlei" 
					placeholder="资源分类" clearable :readonly="ro.ziyuanfenlei"></el-input>
			</el-form-item>
			<el-form-item class="add-item" label="资源价格" prop="ziyuanjiage">
				<el-input-number v-model="ruleForm.ziyuanjiage" placeholder="资源价格" :disabled="ro.ziyuanjiage"></el-input-number>
			</el-form-item>
			<el-form-item class="add-item" label="取消数量" prop="ziyuanshuliang">
				<el-input v-model.number="ruleForm.ziyuanshuliang" 
					placeholder="取消数量" clearable :readonly="ro.ziyuanshuliang"></el-input>
			</el-form-item>
			<el-form-item class="add-item" label="取消金额" prop="tuidingjine">
				<el-input v-model="tuidingjine" placeholder="取消金额" disabled></el-input>
			</el-form-item>
			<el-form-item class="add-item" label="取消原因" prop="quxiaoyuanyin">
				<el-input v-model="ruleForm.quxiaoyuanyin" 
					placeholder="取消原因" clearable :readonly="ro.quxiaoyuanyin"></el-input>
			</el-form-item>
			<el-form-item class="add-item" label="取消时间" prop="quxiaoshijian">
				<el-date-picker
					:disabled="ro.quxiaoshijian"
					value-format="yyyy-MM-dd HH:mm:ss"
					v-model="ruleForm.quxiaoshijian" 
					type="datetime"
					placeholder="取消时间">
				</el-date-picker>
			</el-form-item>

			<el-form-item class="add-btn-item">
				<el-button class="submitBtn"  type="primary" @click="onSubmit(null)">
					<span class="icon iconfont icon-xiugai2"></span>
					<span class="text">提交信息</span>
				</el-button>
				<el-button class="closeBtn" @click="back()">
					<span class="icon iconfont icon-shanchu7"></span>
					<span class="text">取消</span>
				</el-button>
			</el-form-item>
		</el-form>
	</div>
</template>

<script>
	export default {
		data() {
			return {
				id: '',
				baseUrl: '',
				ro:{
					shenqingbianhao : false,
					ziyuanbianhao : false,
					ziyuanmingcheng : false,
					ziyuantupian : false,
					ziyuanfenlei : false,
					ziyuanjiage : false,
					ziyuanshuliang : false,
					tuidingjine : false,
					quxiaoyuanyin : false,
					yonghuzhanghao : false,
					yishenggonghao : false,
					quxiaoshijian : false,
					sfsh : false,
					shhf : false,
					ispay : false,
				},
				type: '',
				userTableName: localStorage.getItem('UserTableName'),
				ruleForm: {
					shenqingbianhao: '',
					ziyuanbianhao: '',
					ziyuanmingcheng: '',
					ziyuantupian: '',
					ziyuanfenlei: '',
					ziyuanjiage: '',
					ziyuanshuliang: '',
					tuidingjine: '',
					quxiaoyuanyin: '',
					yonghuzhanghao: '',
					yishenggonghao: '',
					quxiaoshijian: '',
				},

				rules: {
					shenqingbianhao: [
					],
					ziyuanbianhao: [
					],
					ziyuanmingcheng: [
					],
					ziyuantupian: [
					],
					ziyuanfenlei: [
					],
					ziyuanjiage: [
						{ validator: this.$validate.isNumber, trigger: 'blur' },
					],
					ziyuanshuliang: [
						{ validator: this.$validate.isIntNumer, trigger: 'blur' },
					],
					tuidingjine: [
						{ validator: this.$validate.isNumber, trigger: 'blur' },
					],
					quxiaoyuanyin: [
						{ required: true, message: '取消原因不能为空', trigger: 'blur' },
					],
					yonghuzhanghao: [
					],
					yishenggonghao: [
					],
					quxiaoshijian: [
					],
					sfsh: [
					],
					shhf: [
					],
					ispay: [
					],
				},
				centerType: false,
			};
		},
		computed: {
			sessionForm() {
				return JSON.parse(localStorage.getItem('sessionForm'))
			},
			tuidingjine : {
				get: function () {
					let c = this.ruleForm
					let a = c.ziyuanjiage*c.ziyuanshuliang
					this.ruleForm.tuidingjine = a?Number(Number(a).toFixed(2)):0
					return a?Number(Number(a).toFixed(2)):0
				}
				
			},



		},
		components: {
		},
		created() {
			if(this.$route.query.centerType){
				this.centerType = true
			}
			//this.bg();
			let type = this.$route.query.type ? this.$route.query.type : '';
			this.init(type);
			this.baseUrl = this.$config.baseUrl;
			this.ruleForm.quxiaoshijian = this.getCurDateTime()
		},
		methods: {
			getMakeZero(s) {
				return s < 10 ? '0' + s : s;
			},
			// 下载
			download(file ){
				window.open(`${file}`)
			},
			// 初始化
			init(type) {
				this.type = type;
				if(type=='cross'){
					var obj = JSON.parse(localStorage.getItem('crossObj'));
					for (var o in obj){
						if(o=='shenqingbianhao'){
							this.ruleForm.shenqingbianhao = obj[o];
							this.ro.shenqingbianhao = true;
							continue;
						}
						if(o=='ziyuanbianhao'){
							this.ruleForm.ziyuanbianhao = obj[o];
							this.ro.ziyuanbianhao = true;
							continue;
						}
						if(o=='ziyuanmingcheng'){
							this.ruleForm.ziyuanmingcheng = obj[o];
							this.ro.ziyuanmingcheng = true;
							continue;
						}
						if(o=='ziyuantupian'){
							this.ruleForm.ziyuantupian = obj[o]?obj[o].split(",")[0]:'';
							this.ro.ziyuantupian = true;
							continue;
						}
						if(o=='ziyuanfenlei'){
							this.ruleForm.ziyuanfenlei = obj[o];
							this.ro.ziyuanfenlei = true;
							continue;
						}
						if(o=='ziyuanjiage'){
							this.ruleForm.ziyuanjiage = obj[o];
							this.ro.ziyuanjiage = true;
							continue;
						}
						if(o=='ziyuanshuliang'){
							this.ruleForm.ziyuanshuliang = obj[o];
							this.ro.ziyuanshuliang = true;
							continue;
						}
						if(o=='tuidingjine'){
							this.ruleForm.tuidingjine = obj[o];
							this.ro.tuidingjine = true;
							continue;
						}
						if(o=='quxiaoyuanyin'){
							this.ruleForm.quxiaoyuanyin = obj[o];
							this.ro.quxiaoyuanyin = true;
							continue;
						}
						if(o=='yonghuzhanghao'){
							this.ruleForm.yonghuzhanghao = obj[o];
							this.ro.yonghuzhanghao = true;
							continue;
						}
						if(o=='yishenggonghao'){
							this.ruleForm.yishenggonghao = obj[o];
							this.ro.yishenggonghao = true;
							continue;
						}
						if(o=='quxiaoshijian'){
							this.ruleForm.quxiaoshijian = obj[o];
							this.ro.quxiaoshijian = true;
							continue;
						}
					}
				}else if(type=='edit'){
					this.info()
				}
				// 获取用户信息
				this.$http.get(this.userTableName + '/session', {emulateJSON: true}).then(res => {
					if (res.data.code == 0) {
						var json = res.data.data;
					}
				});

				if (localStorage.getItem('raffleType') && localStorage.getItem('raffleType') != null) {
					localStorage.removeItem('raffleType')
					setTimeout(() => {
						this.onSubmit(null)
					}, 300)
				}
			},

			// 多级联动参数
			// 多级联动参数
			async info() {
				await this.$http.get(`yuyuequxiao/detail/${this.$route.query.id}`, {emulateJSON: true}).then(res => {
					if (res.data.code == 0) {
						this.ruleForm = res.data.data;
					}
				});
			},
			// 提交
			async onSubmit(subMitType=null) {
				await this.$refs["ruleForm"].validate(async valid => {
					if(valid) {
						if(this.ruleForm.tuidingjine==0){
							this.$message.error('取消金额不能为空')
							return false
						}
						if(!this.ruleForm.id) {
							delete this.ruleForm.userid
						}
						if(this.type=='cross'){
							var statusColumnName = localStorage.getItem('statusColumnName');
							var statusColumnValue = localStorage.getItem('statusColumnValue');
							if(statusColumnName && statusColumnName!='') {
								var obj = JSON.parse(localStorage.getItem('crossObj'));
								if(!statusColumnName.startsWith("[")) {
									for (var o in obj){
										if(o==statusColumnName){
											obj[o] = statusColumnValue;
										}
									}
									var table = localStorage.getItem('crossTable');
									await this.$http.post(table+'/update', obj).then(res => {});
								}
							}
						}

						let changeType = true
						let errMsg = ''
						let hasBackType = false
						if(this.type=='cross') {
							await this.$http.post('updateColumn/ziyuanshenqing/2',{
								csuUpdateColumn: 'ziyuanshuliang',
								csuUpdateColumnValue: '-' + this.ruleForm.ziyuanshuliang,
								csuConditionColumn: 'shenqingbianhao',
								csuConditionColumnValue: this.ruleForm.shenqingbianhao
							}).then(rs=>{
								if(rs.data.code!=0) {
									changeType = false
									errMsg = '订单数量删减失败'
								}
							},err=>{
								changeType = false
								errMsg = '订单数量删减失败'
							})
							if(!changeType) {
								this.$message.error(errMsg);
								return false
							}
						}
						await this.$http.post(`yuyuequxiao/${this.ruleForm.id?'update':this.centerType?'save':'add'}`, this.ruleForm).then(async res => {
							if (res.data.code == 0) {
								await this.$message({
									message: '操作成功',
									type: 'success',
									duration: 1500,
									onClose: () => {
										this.$router.go(-1);
										
									}
								});
							} else {
								this.$message({
									message: res.data.msg,
									type: 'error',
									duration: 1500
								});
							}
						});
					}
				});
			},
			// 获取uuid
			getUUID () {
				return new Date().getTime();
			},
			// 返回
			back() {
				this.$router.go(-1);
			},
			ziyuantupianUploadChange(fileUrls) {
				this.ruleForm.ziyuantupian = fileUrls.replace(new RegExp(this.$config.baseUrl,"g"),"");
			},
		}
	};
</script>

